{"schema": 1,
"id": "user.cpu-ram-gauges",
"name": "System Monitor",
"version": "1.0.0",
"description": "Displays CPU and RAM usage as ring gauges.",
"category": "system",
"window": {
    "mode": "tile",
    "size": [120, 120],
    "layer": "desktop"
},
"style": {
    "theme": "glass",
    "accent": "#4a90e2"
},
"permissions": {
    "system": ["cpu", "memory"],
    "network": [],
    "storage": false
},
"settings": [],
"data": {
    "sys": {
        "source": "system",
        "interval": 1000
    }
},
"ui": {
    "blocks": [
        {
            "type": "column",
            "children": [
                {
                    "type": "gauge",
                    "value": "{{ sys.cpu.usage }}",
                    "max": 100,
                    "label": "CPU",
                    "format": "{{ value | percent }}",
                    "color": "#ff6b6b"
                },
                {
                    "type": "gauge",
                    "value": "{{ sys.memory.usage | default(0) }}",
                    "max": 100,
                    "label": "RAM",
                    "format": "{{ value | percent }}",
                    "color": "#4ecdc4"
                }
            ]
        }
    ]
}
}

{"schema": 1,
"id": "user.sticky-note",
"name": "Quick Notes",
"version": "1.0.0",
"description": "A yellow sticky note for quick typing notes.",
"category": "fun",
"window": {
    "mode": "drawer",
    "size": [400, 300],
    "layer": "top",
    "edge": "right"
},
"style": {
    "theme": "glass",
    "accent": "#FFEB3B"
},
"permissions": {
    "system": [],
    "network": [],
    "storage": true
},
"settings": [
    {
        "key": "note_text",
        "type": "text",
        "label": "Note Content",
        "default": ""
    }
],
"data": {
    "note": {
        "source": "storage",
        "interval": 0
    }
},
"ui": {
    "blocks": [
        {
            "type": "columnOuter",
            "children": [
                {
                    "type": "text",
                    "text": "{{ note_text | default('') }}",
                    "size": "lg",
                    "weight": "bold",
                    "align": "center",
                    "color": "#333333",
                    "mono": false,
                    "visible": "{{ settings.note_text }}"
                },
                {
                    "type": "notes",
                    "key": "note_text",
                    "placeholder": "Type here...",
                    "visible": "{{ settings.note_text }}"
                }
            ]
        }
    ]
}
}

{"schema": 1,
"id": "user.today-checklist",
