{"schema": 1,
"id": "user.system-monitor-drawer",
"name": "System Monitor Drawer",
"version": "1.0.0",
"description": "Displays CPU, memory, and disk usage as horizontal bars in a sliding drawer.",
"category": "system",
"window": {
  "mode": "drawer",
  "size": [300, 200],
  "layer": "top",
  "edge": "right"
},
"style": {
  "theme": "glass",
