{"schema": 1,
"id": "user.network-monitor",
"name": "Network Monitor",
"version": "1.0.0",
"description": "Displays real-time download and upload speeds as sparklines.",
"category": "system",
"window": {
    "mode": "tile",
    "size": [300, 200],
    "layer": "desktop"
},
"style": {
    "theme": "glass",
    "accent": "#4a90e2"
},
"permissions": {
    "system": ["network"],
    "network": [],
    "storage": false
},
"settings": [],
"data": {
    "sys": {
        "source": "system",
        "interval": 1000
    }
},
"ui": {
    "blocks": [
        {
            "type": "gridOuter",
            "children": [
                {
                    "type": "columnInner",
                    "children": [
                        {
                            "type": "graphBlock",
                            "value": "{{ sys.network.rx | rate }}",
                            "max": "1000000",  "label": "Download",
                            "format": "{{ value | bytes }}",
                            "color": "#4a90e2",
                            "points": 15
                        }
                    ]
                },
                {
                    "type": "columnInner",
                    "children": [
                        {
                            "type": "graphBlock",
                            "value": "{{ sys.network.tx | rate }}",
                            "max": "1000000",
                            "label": "Upload",
                            "format": "{{ value | bytes }}",
                            "color": "#4a90e2",
                            "points": 15
                        }
                    ]
                }
            ]
        }
    ]
}
}

