{
  "schema": 1,
  "id": "user.network-monitor",
  "name": "Network Monitor",
  "version": "1.0.0",
  "description": "Network monitor with download and upload speed sparklines.",
  "category": "info",
  "window": {
    "mode": "tile",
    "size": [400, 200],
    "layer": "desktop",
    "edge": "left"
  },
  "style": {
    "theme": "glass",
