  "name": "CPU & RAM Monitor",
  "version": "1.0.0",
  "description": "CPU usage as a ring gauge and RAM usage as a bar.",
  "category": "system",
  "window": {
    "mode": "tile",
    "size": [200, 280],
    "layer": "desktop"
  },
  "style": {
    "theme": "glass",
    "accent": "#ef4444"
  },
  "permissions": {
    "system": ["cpu", "memory"],
    "network": [],
    "storage": false
  },
  "settings": [],
  "data": {
    "sys": {
      "source": "system",
      "interval": 1000
    }
  },
  "ui": {
    "blocks": [
      {
        "type": "column",
        "gap": 8,
        "children": [
          {
            "type": "text",
            "text": "CPU",
            "size": "md",
            "weight": "bold",
            "align": "center"
          },
          {
            "type": "gauge",
            "label": "CPU",
            "value": "{{ sys.cpu.usage }}",
            "max": 100,
            "format": "{{ sys.cpu.usage | fixed(0) }}%",
            "color": "#ef4444"
          },
          {
            "type": "text",
            "text": "RAM",
            "size": "md",
            "weight": "bold",
            "align": "center"
          },
          {
            "type": "bar",
            "label": "RAM",
            "value": "{{ sys.memory.used }}",
            "max": "{{ sys.memory.total }}",
            "format": "{{ sys.memory.usage | fixed(0) }}%",
            "color": "#ef4444"
          }
        ]
      }
    ]
  }
}
